using System;
using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonWaitingAreaSetup
    {
        static T Copy<T>(T source,Transform root,Transform target) where T:Component{return target.Find(AnimationUtility.CalculateTransformPath(source.transform,root)).GetComponent<T>();}
        static void Place(RectTransform r,float x,float y,float w,float h){r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);}
        static void Bind(Button b,UnityEngine.Events.UnityAction action){b.onClick=new Button.ButtonClickedEvent();UnityEventTools.AddPersistentListener(b.onClick,action);}
        [MenuItem("Cat Cafe/開発用/UI再生成/待合スペース",false,34)]
        public static void Build()
        {
            var scene=EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();var source=preview.GetComponent<PythonDayOffPanel>();var root=source.panel.transform.parent;var old=root.Find("Waiting Area");if(old!=null)UnityEngine.Object.DestroyImmediate(old.gameObject);
            var p=preview.GetComponent<PythonWaitingAreaPanel>() ?? preview.gameObject.AddComponent<PythonWaitingAreaPanel>();p.panel=UnityEngine.Object.Instantiate(source.panel,root);p.panel.name="Waiting Area";var s=source.panel.transform;var t=p.panel.transform;
            p.title=Copy(source.title,s,t);p.details=Copy(source.details,s,t);p.notice=Copy(source.notice,s,t);p.confirmationText=Copy(source.confirmationText,s,t);p.confirmation=t.Find(AnimationUtility.CalculateTransformPath(source.confirmation.transform,s)).gameObject;
            p.purchase=Copy(source.proceed,s,t);p.close=Copy(source.close,s,t);p.confirm=Copy(source.confirm,s,t);p.cancel=Copy(source.cancel,s,t);
            p.upgrade=UnityEngine.Object.Instantiate(p.purchase,p.purchase.transform.parent);p.upgrade.name="Upgrade Waiting Area";
            Place(p.purchase.GetComponent<RectTransform>(),24,550,280,40);Place(p.upgrade.GetComponent<RectTransform>(),320,550,280,40);Place(p.close.GetComponent<RectTransform>(),616,550,300,40);
            p.purchase.GetComponentInChildren<Text>().text="購入・1段階目（確認）";p.upgrade.GetComponentInChildren<Text>().text="2段階目へ強化（確認）";
            Bind(p.purchase,p.Purchase);Bind(p.upgrade,p.Upgrade);Bind(p.close,p.Close);Bind(p.confirm,p.Confirm);Bind(p.cancel,p.Cancel);p.confirmation.SetActive(false);p.panel.SetActive(false);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);PythonEventListSetup.Build();Debug.Log("CAT_CAFE_WAITING_AREA_UI_OK");
        }
        public static void BuildAndVerify()
        {
            Build();var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(client,preview);
            var state=PythonServiceSetup.Sample();state.instance_id="waiting-area-test";state.can_set_shifts=true;state.closed=false;state.required_action="";state.funds=3000;
            state.waiting_area=new PythonWaitingArea{status="未購入",capacity=4,max_wait_ticks=8,operating_cost=60,notes="購入・強化した日の営業から待機上限と待機猶予に適用します。\n当日から日次運営費が増え、休業日にも発生します。各操作は1回限りです。\n支払い後に資金が残る必要があります。席数や飼育枠は増えません。",details="待合スペース：未購入 / 所持金：3000\n現在：待機上限4人 / 待機猶予8刻\n待合の維持費0 / 日次運営費合計60\n\n購入・強化した日の営業から待機上限と待機猶予に適用します。\n当日から日次運営費が増え、休業日にも発生します。各操作は1回限りです。\n支払い後に資金が残る必要があります。席数や飼育枠は増えません。\n\n解放条件\n購入：人気第1段階達成後\n2段階目：購入済み・人気第2段階達成後\n営業準備中に操作できます。\n\n購入（1段階目）：費用800 / 資金3000 → 2200\n待機上限4 → 5人 / 待機猶予8 → 10刻\n維持費0 → 10 / 日次運営費60 → 70\n\n購入・強化履歴\nまだ記録はありません。",actions=new[]{new PythonWaitingAreaAction{kind="purchase_waiting_area",label="購入（1段階目）",can_execute=true,cost=800,funds_after=2200,capacity_before=4,capacity_after=5,wait_before=8,wait_after=10,daily_after=10,operating_before=60,operating_after=70},new PythonWaitingAreaAction{kind="upgrade_waiting_area",label="2段階目へ強化",reason="人気第2段階達成後",cost=1200,funds_after=1800,capacity_before=5,capacity_after=6,wait_before=10,wait_after=12,daily_before=10,daily_after=20,operating_before=70,operating_after=80}}};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});apply();var p=preview.GetComponent<PythonWaitingAreaPanel>();var list=preview.GetComponent<PythonEventListPanel>();list.Open();if(list.entries.Length!=21 || !list.entries[18].interactable)throw new Exception("Waiting area entry failed");list.WaitingArea();if(list.panel.activeSelf || !p.panel.activeSelf || !p.purchase.interactable || p.upgrade.interactable)throw new Exception("Waiting area navigation/gates failed");Capture(preview,"Logs/WaitingArea.png");p.Purchase();CheckConfirmation(p,"60 → 70");Capture(preview,"Logs/WaitingAreaConfirmation.png");p.Cancel();if(typeof(PythonStateClient).GetField("pending",f).GetValue(client)!=null)throw new Exception("Waiting cancel queued action");p.Purchase();state.revision++;apply();if(p.confirmation.activeSelf)throw new Exception("Stale waiting confirmation retained");p.Disconnect();if(p.purchase.interactable || p.confirm.interactable)throw new Exception("Offline waiting area enabled");apply();
            state.waiting_area.actions[0].can_execute=false;state.waiting_area.details="購入：人気第1段階達成後に解放されます。";state.revision++;apply();if(p.purchase.interactable || !p.details.text.Contains("第1段階"))throw new Exception("Waiting first stage gate failed");state.waiting_area.actions[0].can_execute=true;state.revision++;apply();p.Purchase();p.Confirm();CheckQueue(client,f,"purchase_waiting_area");
            typeof(PythonStateClient).GetField("pending",f).SetValue(client,null);state.revision++;state.waiting_area.status="購入済み";state.waiting_area.actions[0].can_execute=false;state.waiting_area.actions[1].can_execute=true;state.waiting_area.details="待合スペース：購入済み\n待機上限5人 / 待機猶予10刻 / 維持費10\n\n購入・強化履歴\n2日目：購入 / 支払額800\n\n2段階目：人気第2段階達成済み";apply();p.Upgrade();CheckConfirmation(p,"70 → 80");Capture(preview,"Logs/WaitingAreaUpgrade.png");p.Confirm();CheckQueue(client,f,"upgrade_waiting_area");
            typeof(PythonStateClient).GetField("pending",f).SetValue(client,null);state.revision++;state.waiting_area.status="2段階目まで強化済み";state.waiting_area.actions[1].can_execute=false;apply();if(p.purchase.interactable || p.upgrade.interactable || !p.details.text.Contains("支払額800"))throw new Exception("Completed waiting/history failed");state.instance_id="loaded";apply();if(p.panel.activeSelf)throw new Exception("Waiting area retained across load");state.waiting_area=null;state.revision++;apply();list.Open();if(list.entries[18].interactable)throw new Exception("Legacy waiting entry enabled");Debug.Log("CAT_CAFE_WAITING_AREA_DISPLAY_OK");
        }
        static void CheckConfirmation(PythonWaitingAreaPanel p,string expected){Canvas.ForceUpdateCanvases();if(!p.confirmation.activeSelf || !p.confirmationText.text.Contains(expected) || !p.confirmationText.text.Contains("休業日") || p.confirmationText.preferredHeight>p.confirmationText.rectTransform.rect.height || p.confirmation.transform.GetSiblingIndex()!=p.confirmation.transform.parent.childCount-1)throw new Exception("Waiting confirmation missing/clipped/covered");}
        static void CheckQueue(PythonStateClient client,System.Reflection.BindingFlags f,string kind){var row=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);if(row?.kind!=kind || row.choice!="" || row.cat_id!="" || client.CanWaitingArea(kind))throw new Exception("Waiting command queue failed");}
        static void Capture(ContentPreview preview,string path){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{preview,path});}
    }
}
